import{_ as e,o as t,c as o,Q as a}from"./chunks/framework.b67c47e6.js";const n="/assets/panel-axes.5e5677bc.svg",s="/assets/zones-names.1d86d09d.svg",r="/assets/how-found.73a600a1.svg",i="/assets/front-back.d2d9ea26.svg",h="/assets/mistakes.688d0e9c.svg",z=JSON.parse('{"title":"Panel Sides and Coordinates","description":"","frontmatter":{},"headers":[],"relativePath":"guide/panel_coordinates/index.md","filePath":"guide/panel_coordinates/index.md","lastUpdated":null}'),d={name:"guide/panel_coordinates/index.md"},l=a('<h1 id="panel-sides-and-coordinates" tabindex="-1">Panel Sides and Coordinates <a class="header-anchor" href="#panel-sides-and-coordinates" aria-label="Permalink to &quot;Panel Sides and Coordinates&quot;">​</a></h1><p>produuz.it uses one rule for the sides and the coordinates of a panel. The 3D viewer, the drawings, the lists and the machine files all start from it. This page explains the rule, how produuz.it reads it from your model, and which side each screen and each file looks from.</p><nav class="table-of-contents"><ul><li><a href="#the-rule-in-short">The rule in short</a></li><li><a href="#faces-and-zones">Faces and zones</a></li><li><a href="#where-the-sides-come-from">Where the sides come from</a></li><li><a href="#how-produuz-it-places-a-panel">How produuz.it places a panel</a></li><li><a href="#the-front-and-the-back">The front and the back</a></li><li><a href="#which-side-each-screen-and-file-looks-from">Which side each screen and file looks from</a><ul><li><a href="#production-starting-side">Production starting side</a></li></ul></li><li><a href="#when-a-panel-comes-out-wrong">When a panel comes out wrong</a></li><li><a href="#checklist-for-a-new-exporter">Checklist for a new exporter</a></li></ul></nav><h2 id="the-rule-in-short" tabindex="-1">The rule in short <a class="header-anchor" href="#the-rule-in-short" aria-label="Permalink to &quot;The rule in short&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">The rule</p><ul><li>Every panel has a <strong>front</strong> and a <strong>back</strong>. The <strong>front is the outside face</strong> and holds the <strong>positive zones</strong>. The <strong>back is the inside face</strong> and holds the <strong>negative zones</strong>. <strong>Zone 0 is the frame.</strong></li><li><strong>X</strong> runs along the length of the panel, <strong>Y</strong> up its height, <strong>Z</strong> through its thickness, pointing <strong>towards the front</strong>.</li><li>The <strong>origin</strong> is the <strong>bottom-left corner of the frame, seen from the front</strong>, on the outer face of the frame.</li><li>All coordinates are in <strong>millimetres</strong>.</li></ul></div><p><img src="'+n+'" alt="A wall panel with its two faces, its axes and its origin"></p><ol><li><strong>Origin</strong>: the bottom-left corner of the frame seen from the front. It lies on the face of the frame that points to the outside, so the outside sheathing starts at Z = 0.</li><li><strong>X</strong>: along the panel, from left to right seen from the front.</li><li><strong>Y</strong>: up, from the bottom rail to the top rail.</li><li><strong>Z</strong>: through the thickness, from the inside to the outside.</li></ol><h2 id="faces-and-zones" tabindex="-1">Faces and zones <a class="header-anchor" href="#faces-and-zones" aria-label="Permalink to &quot;Faces and zones&quot;">​</a></h2><p>Every part of a panel has a <strong>zone</strong>: the layer it belongs to.</p><p><img src="'+s+'" alt="A panel cut through its thickness, with every name each face goes by"></p><ol><li><strong>Zone 0</strong> is the frame: rails, studs and the other timbers of the structure.</li><li><strong>Z = 0</strong> is the outer face of the frame. Positive zones have a positive Z, negative zones a negative Z.</li><li><strong>Negative zones</strong> are the layers of the inside face, counted outwards from the frame: -1 lies on the frame, -2 on top of -1, and so on.</li><li><strong>Positive zones</strong> are the layers of the outside face, counted the same way: 1 on the frame, 2 on top of 1.</li></ol><p>Each face goes by several names, depending on where you meet it. They always mean the same face:</p><table><thead><tr><th></th><th>Back</th><th>Front</th></tr></thead><tbody><tr><td>Face</td><td>inside</td><td>outside</td></tr><tr><td>Zones</td><td>negative: -1, -2, -3</td><td>positive: 1, 2, 3</td></tr><tr><td>3D viewer and drawings</td><td>Back</td><td>Front</td></tr><tr><td>Machine settings</td><td><em>Inside</em>, e.g. <em>Inside Contour</em>, <em>Nailer zone 1 Inside</em></td><td><em>Outside</em>, e.g. <em>Outside Contour</em>, <em>Nailer zone 1 Outside</em></td></tr><tr><td>IFC layer value</td><td>holds a <code>B</code>: <code>B1</code>, <code>B2</code>, <code>Back2</code></td><td><code>F1</code>, <code>F2</code>, <code>1</code>, <code>2</code></td></tr><tr><td>BTLx</td><td>opposite face</td><td>reference face</td></tr><tr><td>Dutch</td><td>binnenzijde</td><td>buitenzijde</td></tr></tbody></table><p>When the company setting <strong>Zones from 10 are subzones</strong> is on, zones from 10 upwards belong to their main zone in the viewer: zone 12 is shown with zone 1, zone -25 with zone -2. See <a href="/guide/management/#interface-settings">Company settings</a>.</p><h2 id="where-the-sides-come-from" tabindex="-1">Where the sides come from <a class="header-anchor" href="#where-the-sides-come-from" aria-label="Permalink to &quot;Where the sides come from&quot;">​</a></h2><p>produuz.it reads the outside of a panel from the <strong>zones</strong> your model gives to its parts: a positive zone is outside, a negative zone is inside.</p><ul><li><strong>IFC files</strong>: the zone is read with the <em>Zone (layer)</em> rule of your <a href="/guide/management/ifcps/#zone-layer">IFC Parsing Setup</a>. A value that holds a <code>B</code> becomes a negative zone; anything else stays positive.</li><li><strong>BTLx files</strong>: BTLx layer numbers have no sign. The <a href="/guide/management/ifcps/#positive-side-zones">Positive side zones</a> and <a href="/guide/management/ifcps/#negative-side-zones">Negative side zones</a> rules of the parsing setup say which layers belong to each face.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If your model writes the outside layers with a <code>B</code>, or a BTLx setup has no side rules, produuz.it takes the inside for the outside. Every view and every file of that panel is then mirrored. Check one panel in the 3D viewer after setting up a new exporter: <strong>Front</strong> must show the outside face.</p></div><h2 id="how-produuz-it-places-a-panel" tabindex="-1">How produuz.it places a panel <a class="header-anchor" href="#how-produuz-it-places-a-panel" aria-label="Permalink to &quot;How produuz.it places a panel&quot;">​</a></h2><p>When a panel is analysed, produuz.it works out its axes from the frame and the zones:</p><p><img src="'+r+'" alt="What produuz.it reads in the model to place a panel"></p><ol><li><strong>X</strong> follows the longest top rail or bottom rail of zone 0.</li><li><strong>Y</strong> points from the bottom rail to the top rail.</li><li><strong>Z</strong> points from the negative zones to the positive zones. It is read from the plates of zones 1 to 3 and -1 to -3.</li></ol><p>The origin is then the corner of the frame with the lowest X, the lowest Y and the highest Z.</p><p>For this to work, a panel needs:</p><ul><li>at least one <strong>top rail</strong> or <strong>bottom rail</strong> in zone 0, as categorised by your parsing setup;</li><li>at least one <strong>plate</strong> in zones 1 to 3 or -1 to -3. A panel with plates on one face only works too.</li></ul><p>When one of them is missing, the panel analysis says that the <strong>orientation</strong> could not be found. Fix the parsing setup and analyse the panel again.</p><p><strong>Floors and roofs</strong> follow the same rule. The front is the face of the positive zones, whichever way the panel lies in the building, and Y points from the member you categorise as bottom rail to the one you categorise as top rail.</p><div class="info custom-block"><p class="custom-block-title">Best effort panel orientation</p><p>With the company setting <strong>Best effort panel orientation</strong> on, a panel whose orientation cannot be found from its rails and plates is placed from its geometry instead. The viewer and the drawings use it, but the front may come out on the wrong side. With the setting off, such a panel is shown in the coordinates of the model file. Machine files never use it: a panel without a proper orientation is left out of the file and listed in ERRORS.md. See <a href="/guide/management/#interface-settings">Company settings</a>.</p></div><h2 id="the-front-and-the-back" tabindex="-1">The front and the back <a class="header-anchor" href="#the-front-and-the-back" aria-label="Permalink to &quot;The front and the back&quot;">​</a></h2><p>Seen from the back, a panel is the front view mirrored. The same physical corner moves from one side of the picture to the other.</p><p><img src="'+i+'" alt="The same panel seen from the front and from the back, with the corner each one measures from"></p><ol><li><strong>Seen from the front</strong>, the origin is corner <strong>A</strong>, bottom-left, and X runs to the right.</li><li><strong>Drawings seen from the back</strong> keep measuring from corner <strong>A</strong>, which is now at the bottom-right. A length reads the same on the front and on the back drawing.</li><li><strong>MOB files with starting side <em>inside</em></strong> measure the panel from the back, with their zero at corner <strong>B</strong>: the bottom-left corner seen from the back.</li></ol><div class="warning custom-block"><p class="custom-block-title">Drawings and MOB files on the inside face</p><p>A length on a drawing of a negative zone is measured from corner A. An X in a MOB file with starting side <em>inside</em> is measured from corner B, the other end of the panel. Both are correct; they start from opposite ends.</p></div><h2 id="which-side-each-screen-and-file-looks-from" tabindex="-1">Which side each screen and file looks from <a class="header-anchor" href="#which-side-each-screen-and-file-looks-from" aria-label="Permalink to &quot;Which side each screen and file looks from&quot;">​</a></h2><table><thead><tr><th>Where</th><th>Seen from</th><th>Measured from</th></tr></thead><tbody><tr><td><a href="/guide/viewer/#_3d-model">3D viewer</a></td><td>Opens on the <strong>front</strong>. <strong>Front</strong> and <strong>Back</strong> buttons turn it.</td><td>—</td></tr><tr><td><a href="/guide/management/production_lines/#drawing-setups">Panel drawings</a></td><td>Zone 0 and positive zones from the <strong>front</strong>. Negative zones from the <strong>back</strong>. A custom branch from the back only when all its parts are in negative zones.</td><td>Corner A: bottom-left on a front drawing, bottom-right on a back drawing. Heights from the bottom.</td></tr><tr><td>Part drawings</td><td>Each plate from the face that points away from the frame.</td><td>The part&#39;s own corner.</td></tr><tr><td><a href="/guide/machine_files/formats/panel_mob2/">MOB v1 and MOB v2</a></td><td>The <strong>Production starting side</strong> of the station that owns zone 0. <em>Inside</em>, the default, reads the panel from the <strong>back</strong>; <em>outside</em> from the <strong>front</strong>.</td><td><em>Inside</em>: corner B. <em>Outside</em>: corner A. The <strong>Machine zero</strong> of the machine setup can move it to the other end.</td></tr><tr><td>Panel BTLx</td><td>The <strong>Starting side</strong> of the job, <em>outside</em> by default.</td><td><em>Outside</em>: corner A. <em>Inside</em>: corner B. X = 0 at the left edge of the frame, Y = 0 at its bottom edge.</td></tr><tr><td><a href="/guide/machine_files/formats/frame_mtf/">MTF</a></td><td>Always from the <strong>back</strong>.</td><td>Corner B.</td></tr><tr><td>Part files: <a href="/guide/machine_files/formats/wood_btl/">BTL</a>, BTLx parts, <a href="/guide/machine_files/formats/wood_bvx/">BVX</a>, <a href="/guide/machine_files/formats/generic_wood_csv/">Generic Wood CSV</a>, <a href="/guide/machine_files/formats/plates_ardis/">Ardis</a>, <a href="/guide/machine_files/formats/plates_xcs/">XCS</a>, <a href="/guide/machine_files/formats/plates_cix/">CIX</a>, <a href="/guide/machine_files/formats/plates_dxf/">DXF</a>, <a href="/guide/machine_files/formats/steel_nc/">DSTV</a></td><td>Each part on its own, in the position the machine needs.</td><td>The part&#39;s own corner. The panel coordinates are not used.</td></tr></tbody></table><p>A plate has one reference and one drawing, whichever face it is mounted on. Two plates with the same shape in zone 1 and in zone -1 are the same plate in the lists. If they must be told apart, model them mirrored.</p><h3 id="production-starting-side" tabindex="-1">Production starting side <a class="header-anchor" href="#production-starting-side" aria-label="Permalink to &quot;Production starting side&quot;">​</a></h3><p>The starting side says which face of the panel is clad first on a panel line:</p><ul><li><strong>Inside</strong> (default): the frame is built, the inside face (negative zones) is clad, the panel is turned over, then the outside face (positive zones) is clad.</li><li><strong>Outside</strong>: the other way round.</li></ul><p>It also decides which face the MOB file measures the panel from. The value of the station that owns zone 0 applies to the whole line. See <a href="/guide/machine_files/formats/panel_mob2/#zones-and-faces">MOB v2</a>.</p><p>Some machine settings change the side or the corner for one station only: <strong>Switch direction X-axis</strong>, <strong>Switch direction Y-axis</strong> and <strong>Machine zero</strong> on the Mobi One, and the face inversions on the Frame Station. Leave them at their defaults unless one station comes out mirrored. See <a href="/guide/machine_files/machines/mobi_one/#when-a-file-comes-out-mirrored">Mobi One</a> and <a href="/guide/machine_files/machines/frame_station/">Frame Station</a>.</p><h2 id="when-a-panel-comes-out-wrong" tabindex="-1">When a panel comes out wrong <a class="header-anchor" href="#when-a-panel-comes-out-wrong" aria-label="Permalink to &quot;When a panel comes out wrong&quot;">​</a></h2><p><img src="'+h+'" alt="Three panels seen from the front: as modelled, with the zone signs swapped, with the rails swapped"></p><ol><li><strong>As modelled</strong>: seen from the front, the panel looks as it does from outside the building.</li><li><strong>Zone signs swapped</strong>: the inside layers have positive zones and the outside layers negative ones. The front shows the inside face, and the panel is mirrored left to right everywhere.</li><li><strong>Rails swapped</strong>: the top rail is categorised as bottom rail and the other way round. Y points down, so X turns too: the panel is turned half a turn.</li></ol><table><thead><tr><th>What you see</th><th>Where to look</th></tr></thead><tbody><tr><td>The viewer&#39;s <strong>Front</strong> shows the inside face</td><td>The zones of the IFC export (<code>F</code>/<code>B</code>) or the BTLx side rules. See <a href="/guide/management/ifcps/#zone-layer">Zone (layer)</a>.</td></tr><tr><td>The panel is upside down and mirrored</td><td>The <em>Top rail</em> and <em>Bottom rail</em> categories of the parsing setup.</td></tr><tr><td>The analysis says the orientation could not be found</td><td>A top or bottom rail in zone 0, and a plate in zones 1 to 3 or -1 to -3.</td></tr><tr><td>The panel is right in the viewer, but one machine file is mirrored</td><td>The machine settings of that station. See <a href="/guide/machine_files/machines/mobi_one/#when-a-file-comes-out-mirrored">When a file comes out mirrored</a>.</td></tr><tr><td>A back drawing and a MOB file give different X values</td><td>Expected with starting side <em>inside</em>: they measure from opposite ends. See <a href="#the-front-and-the-back">The front and the back</a>.</td></tr></tbody></table><h2 id="checklist-for-a-new-exporter" tabindex="-1">Checklist for a new exporter <a class="header-anchor" href="#checklist-for-a-new-exporter" aria-label="Permalink to &quot;Checklist for a new exporter&quot;">​</a></h2><ol><li>The frame is zone 0.</li><li>The outside layers are positive zones (<code>F1</code>, <code>F2</code>, or <code>1</code>, <code>2</code>) and the inside layers negative ones (<code>B1</code>, <code>B2</code>, or <code>-1</code>, <code>-2</code>), counted outwards from the frame.</li><li>The top and bottom rails of the frame are categorised as such in the parsing setup.</li><li>For BTLx, the parsing setup declares the positive and negative side zones.</li><li>In the 3D viewer, <strong>Front</strong> shows the outside face, with the bottom rail at the bottom.</li></ol>',47),c=[l];function f(m,g,p,u,w,b){return t(),o("div",null,c)}const k=e(d,[["render",f]]);export{z as __pageData,k as default};
